create table if not exists public.vital_sign_alert_rules(id bigint generated by default as identity primary key,facility_id uuid not null references public.facilities(id) on delete cascade,vital_code text not null,display_name text not null,unit text not null,normal_low numeric,normal_high numeric,critical_low numeric,critical_high numeric,patient_context jsonb not null default '{}'::jsonb,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now(),unique(facility_id,vital_code,patient_context),check(normal_low is null or normal_high is null or normal_low<=normal_high),check(critical_low is null or normal_low is null or critical_low<=normal_low),check(critical_high is null or normal_high is null or normal_high<=critical_high));
create table if not exists public.encounter_clinical_workflows(encounter_id bigint primary key references public.encounters(id) on delete cascade,patient_id bigint not null references public.patients(id) on delete cascade,subjective text,objective text,assessment text,plan text,physical_exam text,presumed_diagnosis text,current_step text not null default 'subjective' check(current_step in ('subjective','objective','assessment','plan','physical_exam','presumed_diagnosis','laboratory','imaging','diagnosis','complete')),completed_at timestamptz,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now());
create table if not exists public.terminology_concepts(id bigint generated by default as identity primary key,terminology_release_id bigint not null references public.terminology_releases(id) on delete cascade,code text not null,entity_uri text not null,display text not null,language_code text not null default 'en',searchable_text text not null,active boolean not null default true,unique(terminology_release_id,code,language_code));
create table if not exists public.diagnostic_suggestion_rules(id bigint generated by default as identity primary key,facility_id uuid references public.facilities(id) on delete cascade,terminology_concept_id bigint not null references public.terminology_concepts(id),rule_name text not null,evidence_requirements jsonb not null,source_url text not null,reviewed_by uuid references auth.users(id),reviewed_at timestamptz,active boolean not null default false);
alter table public.vital_sign_alert_rules enable row level security;alter table public.encounter_clinical_workflows enable row level security;alter table public.terminology_concepts enable row level security;alter table public.diagnostic_suggestion_rules enable row level security;
create policy vital_rules_read on public.vital_sign_alert_rules for select to authenticated using(private.is_platform_root() or private.is_facility_member(facility_id));
create policy vital_rules_manage on public.vital_sign_alert_rules for all to authenticated using(private.is_platform_root() or private.is_facility_admin(facility_id)) with check(private.is_platform_root() or private.is_facility_admin(facility_id));
create policy encounter_workflow_access on public.encounter_clinical_workflows for all to authenticated using(private.is_platform_root() or exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id))) with check(private.is_platform_root() or exists(select 1 from public.patients p where p.id=patient_id and p.facility_id is not null and private.is_facility_member(p.facility_id)));
create policy terminology_concepts_read on public.terminology_concepts for select to authenticated using(exists(select 1 from public.terminology_releases r where r.id=terminology_release_id and r.active));
create policy terminology_concepts_manage on public.terminology_concepts for all to authenticated using(private.is_platform_root()) with check(private.is_platform_root());
create policy diagnostic_rules_read on public.diagnostic_suggestion_rules for select to authenticated using(active and (facility_id is null or private.is_platform_root() or private.is_facility_member(facility_id)));
create policy diagnostic_rules_manage on public.diagnostic_suggestion_rules for all to authenticated using(private.is_platform_root() or (facility_id is not null and private.is_facility_admin(facility_id))) with check(private.is_platform_root() or (facility_id is not null and private.is_facility_admin(facility_id)));
grant select,insert,update,delete on public.vital_sign_alert_rules,public.encounter_clinical_workflows,public.terminology_concepts,public.diagnostic_suggestion_rules to authenticated;grant usage,select on all sequences in schema public to authenticated;
create index if not exists terminology_concepts_search_idx on public.terminology_concepts using gin(to_tsvector('simple',searchable_text));create index if not exists workflow_patient_idx on public.encounter_clinical_workflows(patient_id,updated_at desc);
